def sum_gt(xs, thresh):
    return sum([x for x in xs if x > thresh])


def count_gt(xs, thresh):
    return len([x for x in xs if x > thresh])


def safe_div(num, den):
    return 0.0 if den == 0 else num / den


def dag_ood_solve(xs):
    val_a = sum_gt(xs, 10)
    val_b = count_gt(xs, 10)
    return safe_div(val_a, val_b)
